@Series {
    epsilon:String = "0.001";
    result:String = "Задайте ε и выберите способ вычисления.";
    +SetEpsilon(value:String)->String { epsilon = value; return epsilon; }
    +While()->String { result = lab::While(std::text::toNumber(epsilon)); return result; }
    +For()->String { result = lab::For(std::text::toNumber(epsilon)); return result; }
    +RepeatUntil()->String { result = lab::RepeatUntil(std::text::toNumber(epsilon)); return result; }
    +GoTo()->String { result = lab::GoTo(std::text::toNumber(epsilon)); return result; }
}
@Series #series;
@UI.Column #root {
    padding:16; gap:12;
    @UI.Text #title { text:"Лабораторная № 2 · вариант 6";fontSize:24; }
    @UI.Text #formula { text:"aₙ = 1/2ⁿ + 1/3ⁿ, n ≥ 1. Суммируем члены больше ε."; }
    @UI.TextInput #accuracy { label:"Точность ε (положительное число)";value <= series.epsilon; }
    @UI.Button #whileButton {text:"While · условие перед телом";}
    @UI.Button #forButton {text:"For · перебор номеров";}
    @UI.Button #repeatButton {text:"Repeat–until · условие после тела";}
    @UI.Button #gotoButton {text:"GoTo · переход к началу";}
    @UI.Text #answer {text <= series.result;}
}
accuracy.change ~> series::SetEpsilon(value:event.value);
whileButton.clicked ~> series::While();
forButton.clicked ~> series::For();
repeatButton.clicked ~> series::RepeatUntil();
gotoButton.clicked ~> series::GoTo();
